Object.assign(SNIP,{"l49guard": "#include <mutex>\nmutex m;                               // khóa bảo vệ dem\nvoid tang() {\n    for (int i = 0; i < 1000; i++) {\n        lock_guard<mutex> khoa(m);     // khóa (chờ nếu luồng khác đang giữ)\n        dem++;                         // vùng găng: mỗi lúc chỉ một luồng ở đây\n    }                                  // khoa hết phạm vi: tự mở khóa (RAII)\n}", "l49race": "int dem = 0;               // dùng chung cho hai luồng\nvoid tang() { for (int i = 0; i < 1000; i++) dem++; }\n// dem++ thật ra là 3 bước: ĐỌC dem → cộng 1 → GHI dem.\n// Luồng A đọc 5, luồng B cũng đọc 5, A ghi 6, B ghi 6: mất một lần tăng."});PRESET_NOTES["l49"]={"Lỗi: tranh chấp dữ liệu": "Bấm Từng bước và theo dõi các ô cam: một luồng đọc dem, bị tạm dừng trước khi ghi; luồng kia đọc cùng giá trị đó. Hai lần ghi chồng lên nhau thì mất một lần tăng, nên dem nhỏ hơn 20. Trên máy thật với n nhỏ có khi vẫn ra 20; tăng n lên 100000 sẽ thấy sai gần như mọi lần.", "Ví dụ: sửa bằng mutex lock/unlock": "Giữa lock và unlock chỉ có một luồng được chạy. Luồng kia tới m.lock() lúc mutex đang bị giữ thì phải chờ (ô đỏ “phải chờ”). Kết quả luôn là 20.", "Ví dụ: lock_guard tự mở khóa": "lock_guard khóa khi được tạo ở đầu mỗi vòng lặp và tự mở khi hết vòng (biến khoa bị hủy). Không thể quên unlock.", "Ví dụ: vùng găng ngắn": "Mỗi luồng cộng vào biến cục bộ rieng (không ai dùng chung nên không cần khóa), rồi chỉ khóa một lần để cộng vào tong. Ít lần khóa hơn hẳn ví dụ trước nên các luồng ít phải chờ nhau.", "Ví dụ: mutex trong một lớp": "Đặt mutex cạnh dữ liệu nó bảo vệ, và mọi hàm đụng tới du đều khóa. Kiểm tra x > du và trừ du nằm trong cùng một lần khóa, nên không có luồng nào chen vào giữa.", "Lỗi: deadlock do khóa ngược thứ tự": "Luồng 1 khóa m1 rồi chờ m2, luồng 2 khóa m2 rồi chờ m1: hai luồng chờ nhau mãi. Trên máy thật chương trình treo (có lần may mắn chạy qua). Sửa: cả hai hàm khóa m1 trước, m2 sau.", "Lỗi: quên unlock": "Nhánh return thoát khỏi hàm khi mutex vẫn đang bị khóa; luồng còn lại chờ mãi ở m.lock(). Đây là lý do nên dùng lock_guard: nó mở khóa ở mọi đường ra."};EX_HINTS["l49"]=[["Code mẫu có tranh chấp: chạy thử sẽ thấy tổng sai.", "Khai báo mutex m; toàn cục và đặt lock_guard<mutex> khoa(m); ngay trước tong += x;"], ["Thêm mutex làm thành viên và lock_guard ở đầu rut, soDu.", "rutA chỉ luồng 1 ghi, rutB chỉ luồng 2 ghi: không cần khóa."], ["map không an toàn khi hai luồng cùng sửa: phải khóa quanh dem[tu[i]]++.", "Lambda lam bắt mọi thứ theo tham chiếu [&] và được truyền cho thread như một hàm."]];
/* ===================== BÀI 49 · mutex & data race ===================== */
/* Bài 49 · mutex & data race
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P49=[{label:"Lỗi: tranh chấp dữ liệu",input:"",code:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nint dem = 0;\nvoid tang(int n) {\n    for (int i = 0; i < n; i++) {\n        dem++;\n    }\n}\nint main() {\n    thread a(tang, 10);\n    thread b(tang, 10);\n    a.join();\n    b.join();\n    cout << \"dem = \" << dem << \" (le ra 20)\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["dem"]}]},{label:"Ví dụ: sửa bằng mutex lock/unlock",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\nusing namespace std;\n\nint dem = 0;\nmutex m;\nvoid tang(int n) {\n    for (int i = 0; i < n; i++) {\n        m.lock();\n        dem++;\n        m.unlock();\n    }\n}\nint main() {\n    thread a(tang, 10);\n    thread b(tang, 10);\n    a.join();\n    b.join();\n    cout << \"dem = \" << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["dem"]}]},{label:"Ví dụ: lock_guard tự mở khóa",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <vector>\nusing namespace std;\n\nmutex m;\nlong long tong = 0;\nvoid cong(int dau, int cuoi) {\n    for (int x = dau; x <= cuoi; x++) {\n        lock_guard<mutex> khoa(m);\n        tong += x;\n    }\n}\nint main() {\n    vector<thread> ds;\n    for (int k = 0; k < 3; k++) {\n        ds.emplace_back(cong, k * 4 + 1, k * 4 + 4);\n    }\n    for (auto& t : ds) t.join();\n    cout << \"Tong 1..12 = \" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["tong"]}]},{label:"Ví dụ: vùng găng ngắn",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <vector>\nusing namespace std;\n\nmutex m;\nlong long tong = 0;\nvoid cong(int dau, int cuoi) {\n    long long rieng = 0;\n    for (int x = dau; x <= cuoi; x++) {\n        rieng += x;\n    }\n    lock_guard<mutex> khoa(m);\n    tong += rieng;\n}\nint main() {\n    vector<thread> ds;\n    for (int k = 0; k < 3; k++) {\n        ds.emplace_back(cong, k * 4 + 1, k * 4 + 4);\n    }\n    for (auto& t : ds) t.join();\n    cout << \"Tong 1..12 = \" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"vars",names:["tong"]}]},{label:"Ví dụ: mutex trong một lớp",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    long long du = 0;\n    mutex m;\npublic:\n    void gui(long long x) {\n        lock_guard<mutex> k(m);\n        du += x;\n    }\n    bool rut(long long x) {\n        lock_guard<mutex> k(m);\n        if (x > du) return false;\n        du -= x;\n        return true;\n    }\n    long long soDu() {\n        lock_guard<mutex> k(m);\n        return du;\n    }\n};\nint main() {\n    TaiKhoan tk;\n    thread a([&tk]() { for (int i = 0; i < 5; i++) tk.gui(100); });\n    thread b([&tk]() { for (int i = 0; i < 5; i++) tk.gui(50); });\n    a.join();\n    b.join();\n    cout << \"So du: \" << tk.soDu() << \"\\n\";\n    cout << (tk.rut(1000) ? \"Rut duoc\" : \"Khong du tien\") << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Lỗi: deadlock do khóa ngược thứ tự",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\nusing namespace std;\n\nmutex m1, m2;\nvoid chuyenAB() {\n    for (int i = 0; i < 3; i++) {\n        lock_guard<mutex> a(m1);\n        lock_guard<mutex> b(m2);\n    }\n}\nvoid chuyenBA() {\n    for (int i = 0; i < 3; i++) {\n        lock_guard<mutex> b(m2);\n        lock_guard<mutex> a(m1);\n    }\n}\nint main() {\n    thread x(chuyenAB);\n    thread y(chuyenBA);\n    x.join();\n    y.join();\n    cout << \"xong\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Lỗi: quên unlock",input:"",code:"#include <iostream>\n#include <thread>\n#include <mutex>\nusing namespace std;\n\nmutex m;\nint dem = 0;\nvoid tang() {\n    m.lock();\n    dem++;\n    if (dem > 0) return;\n    m.unlock();\n}\nint main() {\n    thread a(tang);\n    thread b(tang);\n    a.join();\n    b.join();\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]}];
