makeEx2(document.getElementById("ex-l49"),sim49,[{t:"Cộng dồn an toàn",d:"Nhập k (1 ≤ k ≤ 4) và n. Tạo k luồng, luồng i cộng các số i·n + 1 … (i+1)·n vào biến <code>tong<\/code> dùng chung, mỗi lần cộng một số. Dùng <code>mutex<\/code> (nên dùng <code>lock_guard<\/code>) để kết quả luôn đúng. In <code>tong<\/code>.",tests:[{in:"2 5",out:"55"},{in:"3 4",out:"78"},{in:"1 1",out:"1"}],start:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <vector>\nusing namespace std;\n\nlong long tong = 0;\n// mutex m;\nvoid cong(long long dau, long long cuoi) {\n    for (long long x = dau; x <= cuoi; x++) {\n        tong += x;\n    }\n}\nint main() {\n    int k;\n    long long n;\n    cin >> k >> n;\n    vector<thread> ds;\n    for (int i = 0; i < k; i++) ds.emplace_back(cong, i * n + 1, (i + 1) * n);\n    for (auto& t : ds) t.join();\n    cout << tong << \"\\n\";\n    return 0;\n}",need:/lock_guard|\.lock\s*\(/,needMsg:"Hãy bảo vệ tong bằng mutex."},{t:"Rút tiền nhiều luồng",d:"Lớp <code>TaiKhoan<\/code> có số dư ban đầu S. Có q yêu cầu rút tiền a₁…a_q, chia cho hai luồng: luồng 1 xử lý các yêu cầu ở vị trí chẵn (0, 2, 4…), luồng 2 các vị trí lẻ. Mỗi yêu cầu chỉ được rút nếu đủ tiền (kiểm tra và trừ trong cùng một lần khóa). In số dư cuối và tổng số tiền đã rút được. (Dữ liệu được chọn sao cho kết quả không phụ thuộc thứ tự.)",tests:[{in:"100 4\n30 30 30 30",out:"10\n90"},{in:"50 3\n10 20 5",out:"15\n35"},{in:"10 2\n20 30",out:"10\n0"}],start:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <vector>\nusing namespace std;\n\nclass TaiKhoan {\n    long long du;\n    // mutex m;\npublic:\n    TaiKhoan(long long s) : du(s) {}\n    bool rut(long long x) {\n        if (x > du) return false;\n        du -= x;\n        return true;\n    }\n    long long soDu() { return du; }\n};\nint main() {\n    long long s;\n    int q;\n    cin >> s >> q;\n    vector<long long> a(q);\n    for (auto& x : a) cin >> x;\n    TaiKhoan tk(s);\n    long long rutA = 0, rutB = 0;\n    thread t1([&]() { for (int i = 0; i < q; i += 2) if (tk.rut(a[i])) rutA += a[i]; });\n    thread t2([&]() { for (int i = 1; i < q; i += 2) if (tk.rut(a[i])) rutB += a[i]; });\n    t1.join();\n    t2.join();\n    cout << tk.soDu() << \"\\n\" << rutA + rutB << \"\\n\";\n    return 0;\n}",need:/mutex\s+\w+\s*;[\s\S]*lock_guard/,needMsg:"Hãy thêm mutex vào lớp và khóa trong rut."},{t:"Đếm từ bằng nhiều luồng",d:"Nhập n rồi n từ. Chia các từ cho hai luồng (luồng 1: nửa đầu, luồng 2: nửa sau). Mỗi luồng đếm vào một <code>map&lt;string, int&gt;<\/code> dùng chung, được bảo vệ bằng mutex. Sau khi join, in mỗi từ và số lần xuất hiện theo thứ tự bảng chữ cái.",tests:[{in:"6\nmeo cho meo ga cho meo",out:"cho 2\nga 1\nmeo 3"},{in:"1\nx",out:"x 1"}],start:"#include <iostream>\n#include <thread>\n#include <mutex>\n#include <map>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> tu(n);\n    for (auto& s : tu) cin >> s;\n    map<string, int> dem;\n    // mutex m;\n    // auto lam = [&](int dau, int cuoi) { ... };\n    // thread t1(...), t2(...); join\n    for (auto& [k, v] : dem) cout << k << \" \" << v << \"\\n\";\n    return 0;\n}",need:/thread[\s\S]*lock_guard|lock_guard[\s\S]*thread/,needMsg:"Hãy dùng hai luồng và khóa mutex khi sửa map."}]);

makeQuiz("quiz49","score49",[{"q": "Hai luồng, mỗi luồng chạy <code>dem++<\/code> 1000 lần trên biến dùng chung, không khóa. Kết quả:", "o": ["Luôn là 2000", "Có thể nhỏ hơn 2000 và khác nhau mỗi lần chạy", "Luôn là 1000", "Lỗi biên dịch"], "a": 1, "e": "dem++ gồm đọc, cộng, ghi; hai luồng chen nhau làm mất lần tăng (tranh chấp dữ liệu, hành vi không xác định)."}, {"q": "Vì sao nên dùng <code>lock_guard<\/code> thay cho <code>lock()<\/code>/<code>unlock()<\/code>?", "o": ["Nhanh hơn", "Tự mở khóa khi ra khỏi khối bằng mọi đường (return, ngoại lệ)", "Khóa được nhiều mutex", "Không cần khai báo mutex"], "a": 1, "e": "RAII: hàm hủy của lock_guard luôn chạy."}, {"q": "Luồng A khóa m1 rồi m2; luồng B khóa m2 rồi m1. Nguy cơ là:", "o": ["Tranh chấp dữ liệu", "Deadlock: hai luồng chờ nhau mãi", "Rò rỉ bộ nhớ", "Không có vấn đề gì"], "a": 1, "e": "Khóa theo cùng một thứ tự ở mọi luồng để tránh."}, {"q": "Đoạn nào KHÔNG cần khóa?", "o": ["Hai luồng cùng tăng một biến toàn cục", "Hai luồng cùng push_back vào một vector", "Mỗi luồng chỉ ghi vào phần tử kq[i] của riêng mình", "Một luồng ghi, một luồng đọc cùng biến"], "a": 2, "e": "Không có hai luồng nào đụng cùng một vùng nhớ thì không có tranh chấp."}]);

